import React, { useState } from 'react';
import { Bar } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  PointElement,
  Title,
  Tooltip,
  Legend
} from 'chart.js';
import * as parsers from 'bio-parsers';
import { Buffer } from 'buffer';

// Polyfill Buffer for browser
window.Buffer = Buffer;

ChartJS.register(CategoryScale, LinearScale, BarElement, PointElement, Title, Tooltip, Legend);

const WebRAnalysis = () => {
  const [files, setFiles] = useState([]);
  const [metadata, setMetadata] = useState([]);
  const [results, setResults] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [processingStatus, setProcessingStatus] = useState('');

  const handleFileUpload = (event) => {
    const uploadedFiles = Array.from(event.target.files);
    const validFiles = uploadedFiles.filter(file =>
      file.name.endsWith('.ab1') && file.size <= 10 * 1024 * 1024
    );

    if (validFiles.length !== uploadedFiles.length) {
      setError('Some files are invalid. Please upload .ab1 files under 10MB.');
      return;
    }

    setFiles(validFiles);
    setMetadata(validFiles.map((file) => ({
      fileName: file.name,
      group: ''
    })));
    setError(null);
    setResults(null);
  };

  const handleMetadataChange = (index, field, value) => {
    const newMetadata = [...metadata];
    newMetadata[index][field] = value;
    setMetadata(newMetadata);
  };

  const processFiles = async () => {
    if (!metadata.length) return;

    setLoading(true);
    setError(null);
    setProcessingStatus('Loading analysis tools...');

    try {
      console.log('🔧 Using bio-parsers...');
      console.log('✅ bio-parsers:', parsers);
      const results = [];

      // Prepare group and replicate info
      const replicateCounts = {};
      const processedData = metadata.map((meta, idx) => {
        const group = meta.group.trim() || 'default';
        replicateCounts[group] = (replicateCounts[group] || 0) + 1;
        return {
          file: files[idx],
          fileName: meta.fileName,
          group: group,
          replicate: replicateCounts[group]
        };
      });

      for (let i = 0; i < processedData.length; i++) {
        const { file, fileName, group, replicate } = processedData[i];

        setProcessingStatus(`Reading ${fileName} (${i + 1}/${files.length})...`);

        try {
          console.log(`📄 Reading file: ${fileName}`);
          console.log(`📊 File size: ${file.size} bytes`);

          // Read .ab1 file with bio-parsers - pass the File object directly
          const ab1Data = await parsers.ab1ToJson(file);
          console.log(`🧬 ab1Data:`, ab1Data);

          if (!ab1Data.success || !ab1Data.parsedSequence) {
            console.error('❌ Failed to parse .ab1 file:', ab1Data);
            throw new Error('Failed to parse .ab1 file');
          }

          const seq = ab1Data.parsedSequence;
          console.log(`🧬 parsedSequence:`, seq);

          const peakData = seq.chromatogramData;
          const baseCalls = seq.sequence;
          console.log(`📈 Peak data available:`, !!peakData);
          console.log(`🔤 Base calls length:`, baseCalls?.length);

          if (!peakData || !baseCalls) {
            console.error('❌ Missing data - peakData:', !!peakData, 'baseCalls:', !!baseCalls);
            throw new Error('Missing chromatogram data or base calls');
          }

          setProcessingStatus(`Analyzing ${fileName}...`);

          // Create data frame equivalent in JavaScript
          const sangs = [];
          const aTrace = peakData.aTrace || [];
          const cTrace = peakData.cTrace || [];
          const gTrace = peakData.gTrace || [];
          const tTrace = peakData.tTrace || [];
          const basePosData = peakData.basePos || [];

          for (let j = 0; j < baseCalls.length; j++) {
            const pos = basePosData[j] || j;
            const aArea = aTrace[pos] || 0;
            const cArea = cTrace[pos] || 0;
            const gArea = gTrace[pos] || 0;
            const tArea = tTrace[pos] || 0;
            const totArea = aArea + cArea + gArea + tArea;

            sangs.push({
              index: j + 1,
              baseCall: baseCalls[j],
              aArea,
              cArea,
              gArea,
              tArea,
              totArea,
              aPerc: totArea > 0 ? (100 * aArea / totArea) : 0,
              cPerc: totArea > 0 ? (100 * cArea / totArea) : 0,
              gPerc: totArea > 0 ? (100 * gArea / totArea) : 0,
              tPerc: totArea > 0 ? (100 * tArea / totArea) : 0
            });
          }

          // Filter data (equivalent to R script filtering)
          const sangsFiltered = sangs.filter(s => s.index > 20);
          console.log(`🔍 Filtered data points: ${sangsFiltered.length}`);

          const avgTotArea = sangsFiltered.reduce((sum, s) => sum + s.totArea, 0) / sangsFiltered.length;
          const peakTotAreaCutoff = avgTotArea / 10;
          const sangsFilt = sangsFiltered.filter(s => s.totArea > peakTotAreaCutoff);
          console.log(`✂️ After cutoff filter: ${sangsFilt.length} data points`);

          // Find guide sequence using anchor
          const anchor = "CCAATTAAA";
          const sequence = sangsFilt.map(s => s.baseCall).join('');
          console.log(`🧬 Full sequence length: ${sequence.length}`);

          const anchorPos = sequence.indexOf(anchor);
          console.log(`🎯 Anchor position: ${anchorPos}`);

          if (anchorPos === -1) {
            console.warn(`Anchor not found in ${fileName}, using fallback positions`);
            // Use approximate positions if anchor not found
            const targetPositions = [50, 55, 60, 65, 70, 75]; // Approximate guide positions
            let sumG = 0;
            let sumAll = 0;

            targetPositions.forEach(pos => {
              if (pos < sangsFilt.length) {
                const data = sangsFilt[pos];
                sumG += data.gPerc;
                sumAll += data.aPerc + data.cPerc + data.gPerc + data.tPerc;
              }
            });

            const meanEdit = sumAll > 0 ? (100 * sumG / sumAll) : 0;
            console.log(`📊 Fallback - sumG: ${sumG}, sumAll: ${sumAll}, meanEdit: ${meanEdit}%`);

            results.push({
              file: fileName,
              group: group,
              replicate: replicate,
              value: meanEdit
            });
            console.log(`✅ Result added (fallback):`, results[results.length - 1]);
          } else {
            // Guide starts after anchor
            const guideStartIdx = anchorPos + anchor.length;
            const guideLength = 36;
            const guideEndIdx = guideStartIdx + guideLength - 1;

            // Target positions within guide (8, 13, 18, 23, 28, 33)
            const targetPosInGuide = [8, 13, 18, 23, 28, 33];
            let sumG = 0;
            let sumAll = 0;

            targetPosInGuide.forEach(relPos => {
              const absPos = guideStartIdx + relPos - 1; // -1 for 0-indexing
              if (absPos < sangsFilt.length) {
                const data = sangsFilt[absPos];
                sumG += data.gPerc;
                sumAll += data.aPerc + data.cPerc + data.gPerc + data.tPerc;
              }
            });

            const meanEdit = sumAll > 0 ? (100 * sumG / sumAll) : 0;
            console.log(`📊 Anchor found - sumG: ${sumG}, sumAll: ${sumAll}, meanEdit: ${meanEdit}%`);

            results.push({
              file: fileName,
              group: group,
              replicate: replicate,
              value: meanEdit
            });
            console.log(`✅ Result added (anchor):`, results[results.length - 1]);
          }

        } catch (fileErr) {
          console.error(`Error processing ${fileName}:`, fileErr);
          results.push({
            file: fileName,
            group: group,
            replicate: replicate,
            value: 0,
            error: fileErr.message
          });
        }
      }

      console.log(`🎯 Total results collected: ${results.length}`);
      console.log(`📋 All results:`, results);

      // Group results and create chart
      const grouped = results.reduce((acc, d) => {
        if (d.error) return acc;
        const group = d.group;
        if (!acc[group]) acc[group] = { total: 0, count: 0, samples: [] };
        acc[group].total += d.value;
        acc[group].count++;
        acc[group].samples.push(d);
        return acc;
      }, {});

      console.log(`📊 Grouped data:`, grouped);

      const labels = Object.keys(grouped);
      console.log(`🏷️ Chart labels:`, labels);

      const maxEdit = Math.max(...results.filter(r => !r.error).map(d => d.value || 0));
      const chartMax = Math.min(100, Math.ceil(maxEdit + 10));
      const groupMeans = labels.map(group => grouped[group].total / grouped[group].count);
      console.log(`📈 Group means:`, groupMeans);

      const replicatePoints = {
        label: 'Replicates',
        data: labels.flatMap((group, i) =>
          grouped[group].samples.map(s => ({
            x: labels[i],
            y: s.value
          }))
        ),
        type: 'scatter',
        backgroundColor: '#000',
        pointStyle: 'circle',
        radius: 4,
        order: 1
      };

      const barData = {
        label: 'Mean Editing (%)',
        data: groupMeans,
        backgroundColor: '#C00000',
        borderColor: '#C00000',
        borderWidth: 1,
        order: 2
      };

      const finalResults = {
        labels,
        datasets: [barData, replicatePoints],
        rawData: results,
        chartMax
      };

      console.log(`🎨 Final chart data:`, finalResults);
      setResults(finalResults);
    } catch (err) {
      console.error(err);
      setError(`Error: ${err.message}`);
    } finally {
      setLoading(false);
      setProcessingStatus('');
    }
  };

  const chartOptions = (maxY) => ({
    responsive: true,
    plugins: {
      legend: { display: false },
      title: { display: true, text: 'Editing by Group', color: '#C00000' },
    },
    scales: {
      x: {
        type: 'category',
        title: { display: true, text: 'Group' }
      },
      y: {
        beginAtZero: true,
        max: maxY,
        title: { display: true, text: 'Editing (%)' }
      }
    }
  });

  const exportToCSV = () => {
    if (!results) return;

    const rows = [["File", "Group", "Replicate", "Editing (%)"]];
    metadata.forEach((m, i) => {
      const result = results.rawData[i];
      rows.push([
        m.fileName,
        m.group || 'default',
        result?.replicate || '',
        result?.value != null ? result.value.toFixed(2) : ''
      ]);
    });

    const csvContent = "data:text/csv;charset=utf-8," + rows.map(r => r.join(",")).join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.href = encodedUri;
    link.download = "sanger_results.csv";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="container p-5">
      <h1 className="title is-3 has-text-black mb-4">Browser-Based Sanger Analysis</h1>

      <div className="notification is-info is-light mb-4">
        <p><strong>Running locally in your browser!</strong> Your data never leaves your computer. No server needed!</p>
      </div>

      {/* File upload and analysis buttons */}
      <div className="field is-grouped mb-5" style={{ alignItems: 'center' }}>
        <div className="control is-flex is-align-items-center">
          <div className="file has-name is-rounded">
            <label className="file-label">
              <input
                className="file-input"
                type="file"
                accept=".ab1"
                multiple
                onChange={handleFileUpload}
              />
              <span className="file-cta" style={{ backgroundColor: '#C00000', color: 'white', borderRadius: '20px' }}>
                <span className="file-label">Select Files</span>
              </span>
              <span style={{ color: '#777', paddingLeft: '10px', alignSelf: 'center', display: 'inline-flex' }}>
                {files.length > 0 ? `${files.length} file(s)` : 'No files selected'}
              </span>
            </label>
          </div>
        </div>

        <div className="control">
          <button
            onClick={processFiles}
            className="button"
            style={{
              backgroundColor: '#C00000',
              color: 'white',
              borderRadius: '20px',
              padding: '10px 20px',
              border: 'none'
            }}
            disabled={loading}
          >
            {loading ? 'Processing...' : 'Analyze'}
          </button>
        </div>
      </div>

      {/* Table and Chart */}
      {metadata.length > 0 && (
        <div className="columns" style={{ fontSize: '0.85rem' }}>
          {/* Table */}
          <div className="column is-half">
            <table
              className="table is-bordered has-text-black"
              style={{
                backgroundColor: 'white',
                color: 'black',
                textAlign: 'center',
                verticalAlign: 'middle'
              }}
            >
              <thead style={{ backgroundColor: '#e8e8e8' }}>
                <tr>
                  <th style={{ color: 'black' }}>File</th>
                  <th style={{ color: 'black' }}>Group</th>
                  <th style={{ color: 'black' }}>Replicate</th>
                  <th style={{ color: 'black' }}>% Editing</th>
                </tr>
              </thead>
              <tbody style={{ backgroundColor: '#ffffff' }}>
                {metadata.map((meta, idx) => {
                  const result = results?.rawData?.[idx];
                  const editingVal = result?.value?.toFixed(2) || '';

                  return (
                    <tr key={idx}>
                      <td style={{ color: 'black', verticalAlign: 'middle', textAlign: 'center' }}>{meta.fileName}</td>
                      <td>
                        <input
                          className="input is-small"
                          style={{
                            backgroundColor: 'white',
                            color: 'black',
                            textAlign: 'center',
                            padding: '2px 6px'
                          }}
                          value={meta.group}
                          onChange={e => handleMetadataChange(idx, 'group', e.target.value)}
                        />
                      </td>
                      <td style={{ color: 'black', verticalAlign: 'middle', textAlign: 'center' }}>{result?.replicate || ''}</td>
                      <td style={{ color: 'black', verticalAlign: 'middle', textAlign: 'center' }}>{editingVal}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
            {results && (
              <p style={{ fontSize: '0.85rem', marginTop: '0.5rem' }}>
                <button onClick={exportToCSV} style={{ cursor: 'pointer', color: '#C00000', textDecoration: 'underline' }}>
                  Export to CSV
                </button>
              </p>
            )}
          </div>

          {/* Chart */}
          {results && (
            <div className="column is-half" style={{ minHeight: '400px' }}>
              <Bar data={results} options={chartOptions(results.chartMax)} />
            </div>
          )}
        </div>
      )}

      {processingStatus && <p className="has-text-info">{processingStatus}</p>}
      {error && <div className="has-text-danger">{error}</div>}
    </div>
  );
};

export default WebRAnalysis;
